n.exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://www.mangguoshufang.com/0/list/1.html";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".x-category__box--list span a");
    push("🔥分类🔥", null, 1);
    for (var i = 0; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/1\./,'{{page}}.');      
        push(title, url, size);
        if (i == 8 && a.length > 8) {
            push("🔥进程🔥", null, 1);
        }
        if (i == 11 && a.length > 11) {
            push("🔥字数🔥", null, 1);
        }
        if (i == 16 && a.length > 16) {
            push("🔥章节🔥", null, 1);
        }
        if (i == 21 && a.length > 21) {
            push("🔥版权🔥", null, 1);
        }
        if (i == 27 && a.length > 27) {
            push("🔥费用🔥", null, 1);
        }
        if (i == 30 && a.length > 30) {
            push("🔥字母🔥", null, 1);
        }
    }
} else {
  java.toast("🤔列表刷新失败！！！");
} 
JSON.stringify(result);
